import { z } from 'zod';

/**
 * Client configuration consumed by the delivered modules (K-14.2). Generated by Operatör from the setup form;
 * lives in the client's own accounts. config.schema.json files are generated from this schema.
 */
export const clientConfigSchema = z.object({
  version: z.literal(1),
  client: z.object({
    name: z.string().min(1),
    sector: z.string().nullable(),
    city: z.string().nullable(),
    website: z.string().nullable(),
    instagram: z.string().nullable(),
  }),
  contact: z.object({
    name: z.string().min(1),
    phone: z.string().min(1),
    email: z.email(),
  }),
  hours: z.string().min(1),
  services: z.array(z.string()).min(1),
  faq: z.string(),
  tone: z.enum(['samimi', 'resmi', 'kisa']),
  booking: z.string().nullable(),
  handoff: z.string().nullable(),
  channels: z.object({
    web: z.boolean(),
    instagram: z.boolean(),
    /** K-14.5: adapter ships disabled; the client pays Meta per conversation once enabled. */
    whatsapp: z.boolean(),
  }),
  modules: z.array(z.string()).min(1),
  reminders: z.string().nullable(),
  google_profile: z.string().nullable(),
  software: z.string().nullable(),
  papi: z.object({
    /** Monthly aggregate counts (no personal data) are posted here for the client report. */
    metrics_url: z.string().nullable(),
    metrics_token: z.string().min(40),
  }),
  llm: z.object({
    provider: z.enum(['gemini', 'anthropic', 'openai']),
    model: z.string().min(1),
    /** The client's customers' messages are personal data: a paid, no-training tier is recommended (K-14.5). */
    paid_tier_recommended: z.literal(true),
  }),
});

export type ClientConfig = z.infer<typeof clientConfigSchema>;

export function clientConfigJsonSchema(): Record<string, unknown> {
  return z.toJSONSchema(clientConfigSchema) as Record<string, unknown>;
}
